pragma experimental ABIEncoderV2;

import "./shared/StakingShared.sol";
import "./shared/CheckpointsShared.sol";
import "../../../proxy/modules/interfaces/IFunctionsList.sol";

/**
 * @title Staking Recovery Module (one-off).
 * @notice Salvage module for the September 2026 governance-capture incident.
 *
 * Two single-purpose calls, both restricted to the governance owner (the owner
 * timelock), both with every address hard coded at compile time:
 *
 *  - recoverAttackerStake() moves the SOV staked by both attacker addresses to
 *    the Exchequer, in one call so neither can be left behind. Both their lock
 *    date and their addresses are fixed, so it needs no argument at all.
 *  - recoverGuardiansStake(until) moves back the SOV the Contracts Guardians
 *    Safe staked to defend the vote. Only its lock date is a parameter: that
 *    stake is placed during the incident, so which two-week slot it lands on
 *    depends on when the Safe bundle runs.
 *
 * The module can touch no position but these three and can send tokens nowhere
 * but the Exchequer. Neither call applies the early-unstaking penalty: the
 * attacker's SOV is being returned to users rather than slashed into fee
 * sharing, and the Guardians' stake is a salvage measure, not a yield position.
 *
 * @dev Deliberately carries no whenNotFrozen / whenNotPaused guard. Staking is
 * frozen for the whole incident, so a guarded call would revert on execution
 * and waste the vote. The SIP that adds this module removes it again in the
 * same transaction.
 * */
contract StakingRecoveryModule is IFunctionsList, StakingShared, CheckpointsShared {
    /// @notice The attacker address that staked to seize governance.
    address public constant ATTACKER = 0xac3ecE58a142e829Ef60f224F2FA8F4c98d6dEE8;

    /// @notice The second address the attack voted from, staked after the
    /// @notice malicious proposal was created.
    address public constant ATTACKER_SECONDARY = 0x92972392e3AfBd8C0F417441325b8688e2b7e774;

    /// @notice Contracts Guardians Safe - staked to out-vote the attacker.
    address public constant GUARDIANS_SAFE = 0xDd8e07A57560AdA0A2D84a96c457a5e6DDD488b7;

    /// @notice Exchequer Multisig - receives everything this module recovers.
    address public constant EXCHEQUER = 0x924f5ad34698Fd20c90Fe5D5A8A0abd3b42dc711;

    /// @notice The lock date both attacker addresses staked to.
    /// @dev Fixed, not searched for: staking stays frozen until this proposal
    /// @dev executes, so neither position can be topped up, moved to another
    /// @dev date or opened anywhere else in the meantime. Verified against live
    /// @dev state - each address holds exactly one position, at this date, with
    /// @dev nothing at any other date on the grid.
    uint256 public constant ATTACKER_LOCK_DATE = 1884076095;

    /// @notice Emitted when a stake is recovered without the early-unstaking penalty.
    /// @param staker The account the stake is taken from.
    /// @param amount The number of tokens moved.
    /// @param until The lock date the stake sat on.
    /// @param receiver The receiver of the tokens, always the Exchequer.
    event StakeRecovered(
        address indexed staker,
        uint256 amount,
        uint256 until,
        address indexed receiver
    );

    /**
     * @notice Move everything both attacker addresses have staked to the
     * Exchequer, penalty free.
     * @dev Takes both positions at ATTACKER_LOCK_DATE in one call, and the
     * combined balance leaves in a single transfer, so neither address can be
     * left behind by the proposal. Reverts only when both hold nothing, so a
     * recovery still succeeds if one of them has already been emptied.
     * */
    function recoverAttackerStake() external onlyOwner {
        uint96 total = _take(ATTACKER, ATTACKER_LOCK_DATE);
        total = add96(total, _take(ATTACKER_SECONDARY, ATTACKER_LOCK_DATE), "total overflow"); // SR02
        _payOut(total);
    }

    /**
     * @notice Return the SOV the Contracts Guardians Safe staked to the Exchequer, penalty free.
     * @param until The lock date the Guardians Safe staked to.
     * @dev The date is a parameter because the maximum lock date moves with the
     * two-week grid, so which slot the defensive stake lands on depends on when
     * the Safe bundle runs and is not known when this module is written. The
     * proposal reads it from chain. Reverts when the Safe holds nothing at that
     * date. The staker and the receiver are fixed, so the call can only ever
     * return the Guardians' own stake to the treasury, and the same defensive
     * stake can be made and recovered again in a later incident.
     * */
    function recoverGuardiansStake(uint256 until) external onlyOwner {
        _payOut(_take(GUARDIANS_SAFE, until));
    }

    /**
     * @notice Unstake an account's position at one lock date, without the
     * early-unstaking penalty, crediting the caller with the amount instead of
     * transferring it.
     * @param staker The account the stake is taken from.
     * @param until The lock date to take it from.
     * @return The amount taken, zero when nothing is staked at that date.
     * @dev Checkpoint bookkeeping mirrors a normal withdrawal - daily stake,
     * user stake and delegate stake - so totals and voting power stay
     * consistent. Only the account's own staked balance is taken: voting power
     * delegated to it by others belongs to those stakers and is left where it
     * is. Vesting positions are refused: they unstake through the vesting paths,
     * which keep extra vesting checkpoints this does not write.
     * */
    function _take(address staker, uint256 until) internal returns (uint96) {
        require(!_isVestingContract(staker), "not for vesting contracts"); // SR01

        uint32 checkpoints = numUserStakingCheckpoints[staker][until];
        if (checkpoints == 0) return 0;
        uint96 balance = userStakingCheckpoints[staker][until][checkpoints - 1].stake;
        if (balance == 0) return 0;

        _decreaseDailyStake(until, balance);
        _decreaseUserStake(staker, until, balance);
        _decreaseDelegateStake(delegates[staker][until], until, balance);

        emit StakeRecovered(staker, balance, until, EXCHEQUER);
        emit StakingWithdrawn(staker, balance, until, EXCHEQUER, true);
        return balance;
    }

    /**
     * @notice Send a recovered total to the Exchequer.
     * @param total The combined balance taken from the swept accounts.
     * @dev Reverts when the sweep found nothing, so a proposal that would move
     * no tokens fails loudly rather than emitting an empty success.
     * */
    function _payOut(uint96 total) internal {
        require(total > 0, "nothing staked to recover"); // SR03
        require(SOVToken.transfer(EXCHEQUER, total), "Token transfer failed"); // SR04
    }

    function getFunctionsList() external pure returns (bytes4[] memory) {
        bytes4[] memory functionsList = new bytes4[](2);
        functionsList[0] = this.recoverAttackerStake.selector;
        functionsList[1] = this.recoverGuardiansStake.selector;
        return functionsList;
    }
}
","keccak256":"0x289752575fdd53be081b805aa8130b902df854ce9cfd9f98f9d4d781f71cde1d"},"contracts/governance/Staking/modules/shared/CheckpointsShared.sol":{"content":"pragma solidity ^0.5.17;
pragma experimental ABIEncoderV2;

import "./StakingStorageShared.sol";
import "../../SafeMath96.sol";

/**
 * @title Checkpoints contract.
 * @notice Increases and decreases storage values for users, delegatees and
 * total daily stake.
 * */
contract CheckpointsShared is StakingStorageShared, SafeMath96 {
    /// @notice An event emitted when an account changes its delegate.
    event DelegateChanged(
        address indexed delegator,
        uint256 lockedUntil,
        address indexed fromDelegate,
        address indexed toDelegate
    );

    /// @notice An event emitted when a delegate account's stake balance changes.
    event DelegateStakeChanged(
        address indexed delegate,
        uint256 lockedUntil,
        uint256 previousBalance,
        uint256 newBalance
    );

    /// @notice An event emitted when tokens get staked.
    event TokensStaked(
        address indexed staker,
        uint256 amount,
        uint256 lockedUntil,
        uint256 totalStaked
    );

    /// @notice An event emitted when staked tokens get withdrawn.
    event StakingWithdrawn(
        address indexed staker,
        uint256 amount,
        uint256 until,
        address indexed receiver,
        bool isGovernance
    );

    /// @notice An event emitted when vesting tokens get withdrawn.
    event VestingTokensWithdrawn(address vesting, address receiver);

    /// @notice An event emitted when the owner unlocks all tokens.
    event TokensUnlocked(uint256 amount);

    /// @notice An event emitted when a staking period gets extended.
    event ExtendedStakingDuration(
        address indexed staker,
        uint256 previousDate,
        uint256 newDate,
        uint256 amountStaked
    );

    event AdminAdded(address admin);

    event AdminRemoved(address admin);

    /// @param pauser address to grant power to pause the contract
    /// @param added true - added, false - removed
    event PauserAddedOrRemoved(address indexed pauser, bool indexed added);

    /// @notice An event emitted when a staking is paused or unpaused
    /// @param setPaused true - pause, false - unpause
    event StakingPaused(bool indexed setPaused);

    /// @notice An event emitted when a staking is frozen or unfrozen
    /// @param setFrozen true - freeze, false - unfreeze
    event StakingFrozen(bool indexed setFrozen);

    event ContractCodeHashAdded(bytes32 hash);

    event ContractCodeHashRemoved(bytes32 hash);

    event VestingStakeSet(uint256 lockedTS, uint96 value);

    event TeamVestingCancelled(address indexed caller, address receiver);

    event TeamVestingPartiallyCancelled(
        address indexed caller,
        address receiver,
        uint256 nextStartFrom
    );

    constructor() internal {
        // abstract
    }

    /**
     * @notice Increases the user's vesting stake for a giving lock date and writes a checkpoint.
     * @param lockedTS The lock date.
     * @param value The value to add to the staked balance.
     * */
    function _increaseVestingStake(uint256 lockedTS, uint96 value) internal {
        uint32 nCheckpoints = numVestingCheckpoints[lockedTS];
        uint96 vested = vestingCheckpoints[lockedTS][nCheckpoints - 1].stake;
        uint96 newVest = add96(vested, value, "CP01"); // vested overflow
        _writeVestingCheckpoint(lockedTS, nCheckpoints, newVest);
    }

    /**
     * @notice Decreases the user's vesting stake for a giving lock date and writes a checkpoint.
     * @param lockedTS The lock date.
     * @param value The value to substract to the staked balance.
     * */
    function _decreaseVestingStake(uint256 lockedTS, uint96 value) internal {
        uint32 nCheckpoints = numVestingCheckpoints[lockedTS];
        uint96 vested = vestingCheckpoints[lockedTS][nCheckpoints - 1].stake;
        uint96 newVest = sub96(vested, value, "CP02"); // vested underflow
        _writeVestingCheckpoint(lockedTS, nCheckpoints, newVest);
    }

    /**
     * @notice Writes on storage the user vested amount.
     * @param lockedTS The lock date.
     * @param nCheckpoints The number of checkpoints, to find out the last one index.
     * @param newVest The new vest balance.
     * */
    function _writeVestingCheckpoint(
        uint256 lockedTS,
        uint32 nCheckpoints,
        uint96 newVest
    ) internal {
        uint32 blockNumber = safe32(block.number, "CP03"); // block num > 32 bits

        if (
            nCheckpoints > 0 &&
            vestingCheckpoints[lockedTS][nCheckpoints - 1].fromBlock == blockNumber
        ) {
            vestingCheckpoints[lockedTS][nCheckpoints - 1].stake = newVest;
        } else {
            vestingCheckpoints[lockedTS][nCheckpoints] = Checkpoint(blockNumber, newVest);
            numVestingCheckpoints[lockedTS] = nCheckpoints + 1;
        }
    }

    /**
     * @notice Increases the user's stake for a giving lock date and writes a checkpoint.
     * @param account The user address.
     * @param lockedTS The lock date.
     * @param value The value to add to the staked balance.
     * */
    function _increaseUserStake(address account, uint256 lockedTS, uint96 value) internal {
        uint32 nCheckpoints = numUserStakingCheckpoints[account][lockedTS];
        uint96 staked = userStakingCheckpoints[account][lockedTS][nCheckpoints - 1].stake;
        uint96 newStake = add96(staked, value, "CP04"); // staked overflow
        _writeUserCheckpoint(account, lockedTS, nCheckpoints, newStake);
    }

    /**
     * @notice Decreases the user's stake for a giving lock date and writes a checkpoint.
     * @param account The user address.
     * @param lockedTS The lock date.
     * @param value The value to substract to the staked balance.
     * */
    function _decreaseUserStake(address account, uint256 lockedTS, uint96 value) internal {
        uint32 nCheckpoints = numUserStakingCheckpoints[account][lockedTS];
        uint96 staked = userStakingCheckpoints[account][lockedTS][nCheckpoints - 1].stake;
        uint96 newStake = sub96(staked, value, "CP05"); // staked underflow
        _writeUserCheckpoint(account, lockedTS, nCheckpoints, newStake);
    }

    /**
     * @notice Writes on storage the user stake.
     * @param account The user address.
     * @param lockedTS The lock date.
     * @param nCheckpoints The number of checkpoints, to find out the last one index.
     * @param newStake The new staked balance.
     * */
    function _writeUserCheckpoint(
        address account,
        uint256 lockedTS,
        uint32 nCheckpoints,
        uint96 newStake
    ) internal {
        uint32 blockNumber = safe32(block.number, "CP06"); // block number > 32 bits

        if (
            nCheckpoints > 0 &&
            userStakingCheckpoints[account][lockedTS][nCheckpoints - 1].fromBlock == blockNumber
        ) {
            userStakingCheckpoints[account][lockedTS][nCheckpoints - 1].stake = newStake;
        } else {
            userStakingCheckpoints[account][lockedTS][nCheckpoints] = Checkpoint(
                blockNumber,
                newStake
            );
            numUserStakingCheckpoints[account][lockedTS] = nCheckpoints + 1;
        }
    }

    /**
     * @notice Increases the delegatee's stake for a giving lock date and writes a checkpoint.
     * @param delegatee The delegatee address.
     * @param lockedTS The lock date.
     * @param value The value to add to the staked balance.
     * */
    function _increaseDelegateStake(address delegatee, uint256 lockedTS, uint96 value) internal {
        uint32 nCheckpoints = numDelegateStakingCheckpoints[delegatee][lockedTS];
        uint96 staked = delegateStakingCheckpoints[delegatee][lockedTS][nCheckpoints - 1].stake;
        uint96 newStake = add96(staked, value, "CP07"); // block number > 32 bits
        _writeDelegateCheckpoint(delegatee, lockedTS, nCheckpoints, newStake);
    }

    /**
     * @notice Decreases the delegatee's stake for a giving lock date and writes a checkpoint.
     * @param delegatee The delegatee address.
     * @param lockedTS The lock date.
     * @param value The value to substract to the staked balance.
     * */
    function _decreaseDelegateStake(address delegatee, uint256 lockedTS, uint96 value) internal {
        uint32 nCheckpoints = numDelegateStakingCheckpoints[delegatee][lockedTS];
        uint96 staked = delegateStakingCheckpoints[delegatee][lockedTS][nCheckpoints - 1].stake;
        uint96 newStake = 0;
        // @dev We need to check delegate checkpoint value here,
        //		because we had an issue in `stake` function:
        //		delegate checkpoint wasn't updating for the second and next stakes for the same date
        //		if first stake was withdrawn completely and stake was delegated to the staker
        //		(no delegation to another address).
        // @dev It can be greater than 0, but inconsistent after 3 transactions
        if (staked > value) {
            newStake = sub96(staked, value, "CP08"); // staked underflow
        }
        _writeDelegateCheckpoint(delegatee, lockedTS, nCheckpoints, newStake);
    }

    /**
     * @notice Writes on storage the delegate stake.
     * @param delegatee The delegate address.
     * @param lockedTS The lock date.
     * @param nCheckpoints The number of checkpoints, to find out the last one index.
     * @param newStake The new staked balance.
     * */
    function _writeDelegateCheckpoint(
        address delegatee,
        uint256 lockedTS,
        uint32 nCheckpoints,
        uint96 newStake
    ) internal {
        uint32 blockNumber = safe32(block.number, "CP09"); // block numb > 32 bits
        uint96 oldStake = delegateStakingCheckpoints[delegatee][lockedTS][nCheckpoints - 1].stake;

        if (
            nCheckpoints > 0 &&
            delegateStakingCheckpoints[delegatee][lockedTS][nCheckpoints - 1].fromBlock ==
            blockNumber
        ) {
            delegateStakingCheckpoints[delegatee][lockedTS][nCheckpoints - 1].stake = newStake;
        } else {
            delegateStakingCheckpoints[delegatee][lockedTS][nCheckpoints] = Checkpoint(
                blockNumber,
                newStake
            );
            numDelegateStakingCheckpoints[delegatee][lockedTS] = nCheckpoints + 1;
        }
        emit DelegateStakeChanged(delegatee, lockedTS, oldStake, newStake);
    }

    /**
     * @notice Increases the total stake for a giving lock date and writes a checkpoint.
     * @param lockedTS The lock date.
     * @param value The value to add to the staked balance.
     * */
    function _increaseDailyStake(uint256 lockedTS, uint96 value) internal {
        uint32 nCheckpoints = numTotalStakingCheckpoints[lockedTS];
        uint96 staked = totalStakingCheckpoints[lockedTS][nCheckpoints - 1].stake;
        uint96 newStake = add96(staked, value, "CP10"); // staked overflow
        _writeStakingCheckpoint(lockedTS, nCheckpoints, newStake);
    }

    /**
     * @notice Decreases the total stake for a giving lock date and writes a checkpoint.
     * @param lockedTS The lock date.
     * @param value The value to substract to the staked balance.
     * */
    function _decreaseDailyStake(uint256 lockedTS, uint96 value) internal {
        uint32 nCheckpoints = numTotalStakingCheckpoints[lockedTS];
        uint96 staked = totalStakingCheckpoints[lockedTS][nCheckpoints - 1].stake;
        uint96 newStake = sub96(staked, value, "CP11"); // staked underflow
        _writeStakingCheckpoint(lockedTS, nCheckpoints, newStake);
    }

    /**
     * @notice Writes on storage the total stake.
     * @param lockedTS The lock date.
     * @param nCheckpoints The number of checkpoints, to find out the last one index.
     * @param newStake The new staked balance.
     * */
    function _writeStakingCheckpoint(
        uint256 lockedTS,
        uint32 nCheckpoints,
        uint96 newStake
    ) internal {
        uint32 blockNumber = safe32(block.number, "CP12"); // block num > 32 bits

        if (
            nCheckpoints > 0 &&
            totalStakingCheckpoints[lockedTS][nCheckpoints - 1].fromBlock == blockNumber
        ) {
            totalStakingCheckpoints[lockedTS][nCheckpoints - 1].stake = newStake;
        } else {
            totalStakingCheckpoints[lockedTS][nCheckpoints] = Checkpoint(blockNumber, newStake);
            numTotalStakingCheckpoints[lockedTS] = nCheckpoints + 1;
        }
    }

    /**
     * @notice Get the current balance of an account locked until a certain date.
     * @param account The user address.
     * @param lockDate The lock date.
     * @return The stake amount.
     * */
    function _currentBalance(address account, uint256 lockDate) internal view returns (uint96) {
        uint32 _numUnserStakingCheckpoints = numUserStakingCheckpoints[account][lockDate] - 1;
        return userStakingCheckpoints[account][lockDate][_numUnserStakingCheckpoints].stake;
    }
}
","keccak256":"0x876a54c3cbcbc6e5a1eff589c87b0cf624151c71d1f3f42591ff0df1dd728c07"},"contracts/governance/Staking/modules/shared/StakingShared.sol":{"content":"pragma solidity ^0.5.17;
pragma experimental ABIEncoderV2;

import "./StakingStorageShared.sol";
import "../../SafeMath96.sol";
import "../../../../openzeppelin/SafeMath.sol";
import "../../../../openzeppelin/Ownable.sol";

/**
 * @title Staking modules shared functionality
 */
contract StakingShared is StakingStorageShared, SafeMath96 {
    using SafeMath for uint256;

    uint256 internal constant FOUR_WEEKS = 4 weeks;

    /**
     * @dev Throws if paused.
     */
    modifier whenNotPaused() {
        require(!paused, "paused"); // SS03
        _;
    }

    /**
     * @dev Throws if called by any account other than the owner or admin.
     */
    modifier onlyAuthorized() {
        require(isOwner() || admins[msg.sender], "unauthorized"); // SS01
        _;
    }

    /**
	 * @dev Throws if called by any account other than the owner or admin or pauser.

	modifier onlyAuthorizedOrPauser() {
		require(isOwner() || admins[msg.sender] || pausers[msg.sender], "unauthorized"); // WS02
		_;
	}
	*/

    /**
     * @dev Throws if called by any account other than the owner or pauser.
     */
    modifier onlyPauserOrOwner() {
        require(isOwner() || pausers[msg.sender], "unauthorized"); // SS02
        _;
    }

    /**
     * @dev Throws if called by any account other than pauser.
     * @notice Uncomment when needed
     */
    /*
	modifier onlyPauser() {
		require(pausers[msg.sender], "Not pauser");
		_;
	}
	*/

    /**
     * @dev Throws if frozen.
     */
    modifier whenNotFrozen() {
        require(!frozen, "paused"); // SS04
        _;
    }

    constructor() internal {
        // abstract
    }

    function _notSameBlockAsStakingCheckpoint(uint256 lockDate, address stakeFor) internal view {
        uint32 nCheckpoints = numUserStakingCheckpoints[stakeFor][lockDate];
        bool notSameBlock = userStakingCheckpoints[stakeFor][lockDate][nCheckpoints - 1]
            .fromBlock != block.number;
        require(notSameBlock, "cannot be mined in the same block as last stake"); // S20
    }

    /**
     * @notice Unstaking is possible every 2 weeks only. This means, to
     * calculate the key value for the staking checkpoints, we need to
     * map the intended timestamp to the closest available date.
     * @param timestamp The unlocking timestamp.
     * @return The actual unlocking date (might be up to 2 weeks shorter than intended).
     * */
    function _timestampToLockDate(uint256 timestamp) internal view returns (uint256 lockDate) {
        // Optimize gas costs by reading kickoffTS from storage only once.
        uint256 start = kickoffTS;
        require(timestamp >= start, "timestamp < contract creation"); // WS23
        /**
         * @dev If staking timestamp does not match any of the unstaking dates
         * , set the lockDate to the closest one before the timestamp.
         * E.g. Passed timestamps lies 7 weeks after kickoff -> only stake for 6 weeks.
         * */
        uint256 periodFromKickoff = (timestamp - start) / TWO_WEEKS;
        lockDate = periodFromKickoff * TWO_WEEKS + start;
    }

    /**
     * @notice Determine the current Block Number
     * @dev This is segregated from the _getPriorUserStakeByDate function to better test
     * advancing blocks functionality using Mock Contracts
     * */
    function _getCurrentBlockNumber() internal view returns (uint256) {
        return block.number;
    }

    /**
     * @notice Determine the prior number of stake for an account until a
     * 		certain lock date as of a block number.
     * @dev All functions of Staking contract use this internal version,
     * 		we need to modify public function in order to workaround issue with Vesting.withdrawTokens:
     * return 1 instead of 0 if message sender is a contract.
     * @param account The address of the account to check.
     * @param date The lock date. Adjusted to the next valid lock date, if necessary.
     * @param blockNumber The block number to get the vote balance at.
     * @return The number of votes the account had as of the given block.
     * */
    function _getPriorUserStakeByDate(
        address account,
        uint256 date,
        uint256 blockNumber
    ) internal view returns (uint96) {
        require(blockNumber < _getCurrentBlockNumber(), "not determined"); // WS14

        date = _adjustDateForOrigin(date);
        uint32 nCheckpoints = numUserStakingCheckpoints[account][date];
        if (nCheckpoints == 0) {
            return 0;
        }

        /// @dev First check most recent balance.
        if (userStakingCheckpoints[account][date][nCheckpoints - 1].fromBlock <= blockNumber) {
            return userStakingCheckpoints[account][date][nCheckpoints - 1].stake;
        }

        /// @dev Next check implicit zero balance.
        if (userStakingCheckpoints[account][date][0].fromBlock > blockNumber) {
            return 0;
        }

        uint32 lower = 0;
        uint32 upper = nCheckpoints - 1;
        while (upper > lower) {
            uint32 center = upper - (upper - lower) / 2; /// @dev ceil, avoiding overflow.
            Checkpoint memory cp = userStakingCheckpoints[account][date][center];
            if (cp.fromBlock == blockNumber) {
                return cp.stake;
            } else if (cp.fromBlock < blockNumber) {
                lower = center;
            } else {
                upper = center - 1;
            }
        }
        return userStakingCheckpoints[account][date][lower].stake;
    }

    /**
     * @dev origin vesting contracts have different dates
     * we need to add 2 weeks to get end of period (by default, it's start)
     * @param date The staking date to compute the power for.
     * @return unlocking date.
     */
    function _adjustDateForOrigin(uint256 date) internal view returns (uint256) {
        uint256 adjustedDate = _timestampToLockDate(date);
        //origin vesting contracts have different dates
        //we need to add 2 weeks to get end of period (by default, it's start)
        if (adjustedDate != date) {
            date = adjustedDate + TWO_WEEKS;
        }
        return date;
    }

    /**
     * @notice Compute the weight for a specific date.
     * @param date The unlocking date.
     * @param startDate We compute the weight for the tokens staked until 'date' on 'startDate'.
     * @return The weighted stake the account had as of the given block.
     * */
    function _computeWeightByDate(
        uint256 date,
        uint256 startDate
    ) internal pure returns (uint96 weight) {
        require(date >= startDate, "date < startDate"); // WS18
        uint256 remainingTime = (date - startDate);
        require(MAX_DURATION >= remainingTime, "remaining time > max duration"); // WS19
        /// @dev x = max days - remaining days
        uint96 x = uint96(MAX_DURATION - remainingTime) / (1 days);
        /// @dev w = (m^2 - x^2)/m^2 +1 (multiplied by the weight factor)
        weight = add96(
            WEIGHT_FACTOR,
            mul96(
                MAX_VOTING_WEIGHT * WEIGHT_FACTOR,
                sub96(
                    MAX_DURATION_POW_2,
                    x * x,
                    "weight underflow" // WS20
                ),
                "weight mul overflow" // WS21
            ) / MAX_DURATION_POW_2,
            "overflow on weight" // WS22
        );
    }

    /**
     * @notice Return flag whether the given address is a registered vesting contract.
     * @param stakerAddress the address to check
     */
    function _isVestingContract(address stakerAddress) internal view returns (bool) {
        bool isVesting;
        bytes32 codeHash;

        assembly {
            codeHash := extcodehash(stakerAddress)
        }
        if (address(vestingRegistryLogic) != address(0)) {
            isVesting = vestingRegistryLogic.isVestingAddress(stakerAddress);
        }

        if (isVesting) return true;
        if (vestingCodeHashes[codeHash]) return true;
        return false;
    }
}
","keccak256":"0x4013d5203aae8bd8771fd659cdb987bdde975d38c176d8a4cc749b572646415b"},"contracts/governance/Staking/modules/shared/StakingStorageShared.sol":{"content":"pragma solidity ^0.5.17;
pragma experimental ABIEncoderV2;

import "../../../../openzeppelin/Ownable.sol";
import "../../../../interfaces/IERC20.sol";
import "../../../IFeeSharingCollector.sol";
import "../../../Vesting/IVestingRegistry.sol";

/**
 * @title StakingStorageShared contract is inherited by Staking modules.
 * @notice Just the storage part of stacking contract, no functions,
 * only constant, variables and required structures (mappings).
 * Used by StackingProxy and Checkpoints contracts.
 *
 * What is SOV staking?
 * The purpose of the SOV token is to provide a pseudonymous,
 * censorship-resistant mechanism for governing the parameters of the Sovryn
 * protocol, while aligning the incentives of protocol governors with the
 * long-term success of the protocol. Any SOV token holder can choose to
 * stake (lock up) their tokens for a fixed period of time in return for
 * voting rights in the Bitocracy. Stakers are further incentivised through
 * fee and slashing rewards.
 * */
contract StakingStorageShared is Ownable {
    /// @notice 2 weeks in seconds.
    uint256 constant TWO_WEEKS = 1209600;

    /// @notice The maximum possible voting weight before adding +1 (actually 10, but need 9 for computation).
    uint96 public constant MAX_VOTING_WEIGHT = 9;

    /// @notice weight is multiplied with this factor (for allowing decimals, like 1.2x).
    /// @dev MAX_VOTING_WEIGHT * WEIGHT_FACTOR needs to be < 792, because there are 100,000,000 SOV with 18 decimals
    uint96 public constant WEIGHT_FACTOR = 10;

    /// @notice The maximum duration to stake tokens for.
    uint256 public constant MAX_DURATION = 1092 days;

    /// @notice The maximum duration ^2
    uint96 constant MAX_DURATION_POW_2 = 1092 * 1092;

    /// @notice Default weight scaling.
    uint96 constant DEFAULT_WEIGHT_SCALING = 3;

    /// @notice Range for weight scaling.
    uint96 constant MIN_WEIGHT_SCALING = 1;
    uint96 constant MAX_WEIGHT_SCALING = 9;

    /// @notice The timestamp of contract creation. Base for the staking period calculation.
    uint256 public kickoffTS;

    string name = "SOVStaking";

    /// @notice The token to be staked.
    IERC20 public SOVToken;

    /// @notice A record of each accounts delegate.
    mapping(address => mapping(uint256 => address)) public delegates;

    /// @notice If this flag is set to true, all tokens are unlocked immediately.
    bool public allUnlocked = false;

    /// @notice The EIP-712 typehash for the contract's domain.
    bytes32 public constant DOMAIN_TYPEHASH =
        keccak256("EIP712Domain(string name,uint256 chainId,address verifyingContract)");

    /// @notice The EIP-712 typehash for the delegation struct used by the contract.
    bytes32 public constant DELEGATION_TYPEHASH =
        keccak256("Delegation(address delegatee,uint256 lockDate,uint256 nonce,uint256 expiry)");

    /// @notice Used for stake migrations to a new staking contract with a different storage structure.
    address public newStakingContract;

    /*************************** Checkpoints *******************************/

    /// @notice A checkpoint for marking the stakes from a given block
    struct Checkpoint {
        uint32 fromBlock;
        uint96 stake;
    }

    /// @notice A record of tokens to be unstaked at a given time in total.
    /// For total voting power computation. Voting weights get adjusted bi-weekly.
    /// @dev totalStakingCheckpoints[date][index] is a checkpoint.
    mapping(uint256 => mapping(uint32 => Checkpoint)) public totalStakingCheckpoints;

    /// @notice The number of total staking checkpoints for each date.
    /// @dev numTotalStakingCheckpoints[date] is a number.
    mapping(uint256 => uint32) public numTotalStakingCheckpoints;

    /// @notice A record of tokens to be unstaked at a given time which were delegated to a certain address.
    /// For delegatee voting power computation. Voting weights get adjusted bi-weekly.
    /// @dev delegateStakingCheckpoints[delegatee][date][index] is a checkpoint.
    mapping(address => mapping(uint256 => mapping(uint32 => Checkpoint)))
        public delegateStakingCheckpoints;

    /// @notice The number of total staking checkpoints for each date per delegate.
    /// @dev numDelegateStakingCheckpoints[delegatee][date] is a number.
    mapping(address => mapping(uint256 => uint32)) public numDelegateStakingCheckpoints;

    /// @notice A record of tokens to be unstaked at a given time which per user address (address -> lockDate -> stake checkpoint)
    /// @dev userStakingCheckpoints[user][date][index] is a checkpoint.
    mapping(address => mapping(uint256 => mapping(uint32 => Checkpoint)))
        public userStakingCheckpoints;

    /// @notice The number of total staking checkpoints for each date per user.
    /// @dev numUserStakingCheckpoints[user][date] is a number.
    mapping(address => mapping(uint256 => uint32)) public numUserStakingCheckpoints;

    /// @notice A record of states for signing / validating signatures
    /// @dev nonces[user] is a number.
    mapping(address => uint256) public nonces;

    /*************************** Slashing *******************************/

    /// @notice the address of FeeSharingCollectorProxy contract, we need it for unstaking with slashing.
    IFeeSharingCollector public feeSharing;

    /// @notice used for weight scaling when unstaking with slashing.
    uint96 public weightScaling = DEFAULT_WEIGHT_SCALING;

    /// @notice List of vesting contracts, tokens for these contracts won't be slashed if unstaked by governance.
    /// @dev vestingWhitelist[contract] is true/false.
    mapping(address => bool) public vestingWhitelist;

    /// @dev user => flag whether user has admin role.
    /// @dev multisig should be an admin, admin can invoke only governanceWithdrawVesting function,
    /// 	this function works only with Team Vesting contracts
    mapping(address => bool) public admins;

    /// @dev vesting contract code hash => flag whether it's registered code hash
    mapping(bytes32 => bool) public vestingCodeHashes;

    /// @notice A record of tokens to be unstaked from vesting contract at a given time (lockDate -> vest checkpoint)
    /// @dev vestingCheckpoints[date][index] is a checkpoint.
    mapping(uint256 => mapping(uint32 => Checkpoint)) public vestingCheckpoints;

    /// @notice The number of total vesting checkpoints for each date.
    /// @dev numVestingCheckpoints[date] is a number.
    mapping(uint256 => uint32) public numVestingCheckpoints;

    ///@notice vesting registry contract
    IVestingRegistry public vestingRegistryLogic;

    /// @dev user => flag whether user has pauser role.
    mapping(address => bool) public pausers;

    /// @dev Staking contract is paused
    bool public paused;

    /// @dev Staking contract is frozen
    bool public frozen;

    /// @dev max iterations that can be supported in 1 tx for the withdrawal
    uint256 internal maxVestingWithdrawIterations;

    constructor() internal {
        //abstract
    }
}
